Следующая программа на C++ читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```c++
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string wordToSearch; // Слово для поиска
    std::string currentLine; // Текущая строка
    std::ifstream file; // Объект для чтения файла
    int lineNumber = 1; // Номер текущей строки
    int wordCount = 0; // Количество вхождений слова

    // Ввод слова для поиска
    std::cout << "Enter the word to search: ";
    std::getline(std::cin, wordToSearch);

    // Открытие файла для чтения
    std::cout << "Enter the file name: ";
    std::string fileName;
    std::getline(std::cin, fileName);
    file.open(fileName, std::ios::in);

    if (!file) { // Проверка на ошибки при открытии файла
        std::cerr << "Error opening file: " << fileName << std::endl;
        return 1;
    }

    while (getline(file, currentLine)) { // Чтение файла построчно
        std::size_t position = 0;
        while ((position = currentLine.find(wordToSearch, position)) != std::string::npos) {
            wordCount++; // Увеличение счетчика вхождений слова
            position += wordToSearch.length(); // Переход на следующее вхождение
        }
        lineNumber++; // Увеличение счетчика строк
    }

    file.close(); // Закрытие файла

    std::cout << "Word '" << wordToSearch << "' appears " << wordCount << " times in " << lineNumber << " lines." << std::endl;

    return 0;
}
